export const POSES = [  {"id":"mountain-pose","name":{"en":"Mountain Pose","es":"Postura de la Montaña"},"sanskrit":"Tadasana","level":"gentle","phase":"open","baseSec":45,"helps":["breath","ankles","upper-back"],"loads":[],"sessions":["wake-up","desk-reset","unwind","sleep","strong"],"cue":{"en":"Stand tall and let your weight settle evenly through both feet.","es":"Ponte de pie y deja que el peso se reparta por igual en los dos pies."},"steps":{"en":["Stand with your feet hip-width apart, or with the big toes touching if that feels steady, and the outer edges of the feet parallel.","Stack the pelvis over the ankles, the ribs over the pelvis and the shoulders over the ribs, without tucking the tailbone hard or sticking the bottom out.","Stand for five to ten breaths, noticing where the weight wants to drift."],"es":["Ponte de pie con los pies a la altura de la cadera y los bordes exteriores paralelos.","Apila la pelvis sobre los tobillos, las costillas sobre la pelvis y los hombros sobre las costillas.","Quédate cinco o diez respiraciones notando hacia dónde se desplaza el peso."]},"care":{"en":"Locking the knees back tips the weight into the heels and the lower back. Stand with your back near a wall to check whether you lean forward or back.","es":"Bloquear las rodillas hacia atrás lleva el peso a los talones y a la zona lumbar. Ponte de espaldas cerca de una pared para comprobar si te inclinas hacia delante o hacia atrás."},"img":"images/poses/mountain-pose.webp","stepsImg":"images/poses/mountain-pose-steps.webp","source":"https://yogaphilippines.com/poses/mountain-pose/"},
  {"id":"easy-pose","name":{"en":"Easy Pose","es":"Asiento fácil"},"sanskrit":"Sukhasana","level":"gentle","phase":"rest","baseSec":60,"helps":["hips","lower-back","breath"],"loads":[],"sessions":["desk-reset","unwind","sleep"],"cue":{"en":"Soften the shoulders and let the breath find its own rhythm.","es":"Suelta los hombros y deja que la respiración encuentre su propio ritmo."},"steps":{"en":["Sit on the front edge of a folded blanket or cushion with your legs straight out in front of you.","Let your knees drop toward the floor, and check that they are level with or lower than your hips.","Grow tall from the base of your spine to the crown of your head, chin level."],"es":["Siéntate en el borde delantero de una manta doblada o un cojín, con las piernas extendidas hacia delante.","Cruza las espinillas y deja caer las rodillas hacia el suelo, a la misma altura que las caderas o más abajo.","Crece desde la base de la columna hasta la coronilla, con el mentón nivelado."]},"care":{"en":"Sitting flat on the floor with the knees above the hips rounds the lower back. Sit on a folded blanket or a bolster.","es":"Sentarse en el suelo con las rodillas más altas que las caderas redondea la zona lumbar. Siéntate sobre una manta doblada o un cojín."},"img":"images/poses/easy-pose.webp","stepsImg":"images/poses/easy-pose-steps.webp","source":"https://yogaphilippines.com/poses/easy-pose/"},
  {"id":"cat-cow","name":{"en":"Cat-Cow","es":"Gato-Vaca"},"sanskrit":"Marjaryasana Bitilasana","level":"gentle","phase":"open","baseSec":60,"helps":["upper-back","lower-back","breath"],"loads":["wrists","knees"],"sessions":["wake-up","desk-reset","unwind","sleep"],"cue":{"en":"One shape per inhale, one per exhale. Let the spine do the work.","es":"Una forma por inhalación y otra por exhalación. Deja que la columna haga el trabajo."},"steps":{"en":["Come onto hands and knees with the wrists under the shoulders, the knees under the hips and the tops of the feet on the mat.","Inhale into Cow: tip the tailbone up, let the belly soften toward the floor, and lift the chest and gaze forward without throwing the head back.","Exhale into Cat: tuck the tailbone, press the hands into the floor and round the spine toward the ceiling, letting the head drop."],"es":["Ponte a cuatro patas con las muñecas bajo los hombros y las rodillas bajo las caderas.","Inhala hacia la Vaca: eleva el cóccix, ablanda la barriga y levanta el pecho y la mirada.","Exhala hacia el Gato: recoge el cóccix, empuja el suelo y redondea la columna hacia el techo."]},"care":{"en":"Moving only the neck, nodding the head up and down, leaves the spine still. Fold the mat or put a blanket under the knees if kneeling hurts.","es":"Mover solo el cuello, asintiendo arriba y abajo, deja la columna quieta. Dobla la manta o pon una manta bajo las rodillas si te molesta arrodillarte."},"img":"images/poses/cat-cow.webp","stepsImg":"images/poses/cat-cow-steps.webp","source":"https://yogaphilippines.com/poses/cat-cow/"},
  {"id":"table-top-pose","name":{"en":"Table Top Pose","es":"Postura de la Mesa"},"sanskrit":"Bharmanasana","level":"gentle","phase":"open","baseSec":45,"helps":["upper-back","lower-back"],"loads":["wrists","knees"],"sessions":["wake-up","desk-reset","unwind"],"cue":{"en":"Press the floor away so the shoulders do not sink.","es":"Empuja el suelo para que los hombros no se hundan."},"steps":{"en":["Come onto your hands and knees on the mat, with a blanket under the knees if they are sensitive.","Place your wrists under your shoulders and your knees under your hips, hip-width apart. Spread the fingers and press the whole hand down.","Lengthen the spine from tailbone to crown so the back is flat, the neck long and the gaze on the floor just ahead of the hands."],"es":["Ponte a cuatro patas, con una manta bajo las rodillas si están sensibles.","Coloca las muñecas bajo los hombros y las rodillas bajo las caderas; reparte los dedos y presiona toda la mano.","Alarga la columna del cóccix a la coronilla, con la espalda plana y el cuello largo."]},"care":{"en":"Make fists, rest the hands on blocks, or lower to the forearms if the wrists are sore.","es":"Cierra los puños, apoya las manos en bloques o baja sobre los antebrazos si te duelen las muñecas."},"img":"images/poses/table-top-pose.webp","stepsImg":"images/poses/table-top-pose-steps.webp","source":"https://yogaphilippines.com/poses/table-top-pose/"},
  {"id":"childs-pose","name":{"en":"Child's Pose","es":"Postura del Niño"},"sanskrit":"Balasana","level":"gentle","phase":"rest","baseSec":90,"helps":["lower-back","shoulders","breath"],"loads":["knees"],"sessions":["unwind","sleep","desk-reset"],"cue":{"en":"Let the breath move into the back of your ribs.","es":"Deja que la respiración llegue a la parte de atrás de las costillas."},"steps":{"en":["Kneel on your mat with your big toes touching and your knees together or as wide as the mat.","Sit your hips back toward your heels, only as far as they go easily.","Let your breath move into the back of your ribs, so you can feel your back widen on each inhale."],"es":["Arrodíllate con los dedos gordos juntos y las rodillas juntas o tan separadas como la manta.","Lleva las caderas hacia los talones, solo hasta donde resulte cómodo.","Deja que la respiración llegue a la parte de atrás de las costillas y siente cómo la espalda se ensancha al inhalar."]},"care":{"en":"Forcing the hips down onto the heels when the knees or ankles do not want it. Take the knees wide if the belly, chest or hips feel squashed.","es":"Forzar las caderas sobre los talones cuando las rodillas o los tobillos no están de acuerdo. Abre las rodillas si sientes el vientre, el pecho o las caderas apretados."},"img":"images/poses/childs-pose.webp","stepsImg":"images/poses/childs-pose-steps.webp","source":"https://yogaphilippines.com/poses/childs-pose/"},
  {"id":"supported-childs-pose","name":{"en":"Supported Child's Pose","es":"Postura del Niño apoyada"},"sanskrit":"Salamba Balasana","level":"gentle","phase":"rest","baseSec":120,"helps":["lower-back","shoulders","hips","breath"],"loads":["knees"],"sessions":["unwind","sleep"],"cue":{"en":"Nothing to hold. Let the floor take your weight.","es":"No tienes que sostener nada. Deja que el suelo reciba tu peso."},"steps":{"en":["Bring your big toes together and open your knees about as wide as the mat, drawing the near end of the bolster in between your thighs.","Lengthen forward and lay your belly, chest and head down along the bolster. Put a block under the far end if it feels low.","Turn your head to one side and rest your cheek on the bolster. Let your arms rest on the floor on either side of it, elbows bent."],"es":["Arrodíllate con un cojín cilíndrico delante y una manta doblada cerca.","Abre las rodillas y acuéstate con el vientre, el pecho y la cabeza sobre el cojín.","Gira la cabeza a un lado y apoya la mejilla; los brazos descansan a los lados, con los codos doblados."]},"care":{"en":"Put a folded blanket between the buttocks and the heels if the knees feel tight, and turn your head halfway through.","es":"Coloca una manta doblada entre el buttocks y los talones si las rodillas van tensas, y gira la cabeza a mitad de la postura."},"img":"images/poses/supported-childs-pose.webp","stepsImg":"images/poses/supported-childs-pose-steps.webp","source":"https://yogaphilippines.com/poses/supported-childs-pose/"},
  {"id":"puppy-pose","name":{"en":"Puppy Pose","es":"Postura del Cachorro"},"sanskrit":"Uttana Shishosana","level":"gentle","phase":"open","baseSec":60,"helps":["shoulders","upper-back"],"loads":["wrists"],"sessions":["wake-up","desk-reset","unwind"],"cue":{"en":"Chest sinking, hips staying high.","es":"El pecho baja, las caderas suben."},"steps":{"en":["Walk your hands forward a few hand-lengths, keeping the hips stacked over the knees.","Rest your forehead on the mat, a block or a cushion, with the arms shoulder-width apart.","Let the chest soften down toward the floor while the hips stay lifted. Keep the elbows off the floor if you can."],"es":["Camina las manos hacia delante dejando las caderas sobre las rodillas.","Apoya la frente en la manta, un bloque o un cojín, con los brazos a la altura de los hombros.","Deja que el pecho se suave hacia el suelo mientras las caderas siguen elevadas."]},"care":{"en":"Letting the hips drift back toward the heels turns it into Child's Pose. Rest the chest on a bolster for a milder stretch.","es":"Si las caderas se van hacia los talones se convierte en Postura del Niño. Apoya el pecho en un cojín para un estiramiento más suave."},"img":"images/poses/puppy-pose.webp","stepsImg":"images/poses/puppy-pose-steps.webp","source":"https://yogaphilippines.com/poses/puppy-pose/"},
  {"id":"standing-forward-bend","name":{"en":"Standing Forward Bend","es":"Flexión de pie"},"sanskrit":"Uttanasana","level":"gentle","phase":"open","baseSec":60,"helps":["hamstrings","lower-back","breath"],"loads":[],"sessions":["wake-up","desk-reset","unwind"],"cue":{"en":"Let the head and neck hang heavy.","es":"Deja que la cabeza y el cuello cuelguen pesados."},"steps":{"en":["Breathe in and lengthen up. Breathe out and hinge forward from the hips, keeping the back long at first.","Bend your knees generously and let your hands rest on your shins, on blocks or on the floor.","Stay for five to eight breaths. You can hold opposite elbows and sway gently if that feels good."],"es":["Inhala y alarga hacia arriba. Exhala y dobla desde la cadera, con la espalda larga al principio.","Flexiona generosamente las rodillas y apoya las manos en las espinillas, en bloques o en el suelo.","Quédate cinco o ocho respiraciones y deja que todo el peso caiga en la parte alta de los pies."]},"care":{"en":"Locking the knees and rounding hard through the lower back to reach the floor. Rest the hands on two blocks or a chair seat.","es":"Bloquear las rodillas y redondear la zona lumbar para llegar al suelo. Apoya las manos en dos bloques o en el asiento de una silla."},"img":"images/poses/standing-forward-bend.webp","stepsImg":"images/poses/standing-forward-bend-steps.webp","source":"https://yogaphilippines.com/poses/standing-forward-bend/"},
  {"id":"butterfly-pose","name":{"en":"Butterfly Pose","es":"Postura de la Mariposa"},"sanskrit":"Baddha Konasana","level":"gentle","phase":"main","baseSec":90,"helps":["hips","hamstrings"],"loads":[],"sessions":["unwind","sleep","desk-reset"],"cue":{"en":"Lengthen up on the inhale, fold on the exhale.","es":"Alarga al inhalar, dobla al exhalar."},"steps":{"en":["Bend both knees and draw the soles of the feet together, letting the knees open out to the sides.","Choose your distance: heels close to the pelvis for a stronger stretch along the inner thighs, or a foot or so away for a softer shape.","Hold the ankles or shins rather than pulling on the toes, and lengthen up through the spine as you inhale."],"es":["Flexiona ambas rodillas y junta las plantas de los pies, dejando que las rodillas se abran hacia los lados.","Elige la distancia: los talones cerca de la pelvis para estirar más, o un pie más lejos para una forma más suave.","Sujeta los tobillos o las espinillas, no los dedos de los pies, y alarga la columna al inhalar."]},"care":{"en":"Bouncing the knees hard jars the inner groin. A gentle flutter is fine. Put a block under each knee so the legs can release.","es":"Bailar con fuerza las rodillas golpea la parte interna de la ingle. Un vaivén suave está bien. Pon un bloque bajo cada rodilla para que las piernas se liberen."},"img":"images/poses/butterfly-pose.webp","stepsImg":"images/poses/butterfly-pose-steps.webp","source":"https://yogaphilippines.com/poses/butterfly-pose/"},
  {"id":"seated-forward-bend","name":{"en":"Seated Forward Bend","es":"Flexión sentado"},"sanskrit":"Paschimottanasana","level":"gentle","phase":"main","baseSec":75,"helps":["hamstrings","lower-back"],"loads":[],"sessions":["unwind","sleep","wake-up"],"cue":{"en":"Lead with the chest, not the head.","es":"Guide con el pecho, no con la cabeza."},"steps":{"en":["Breathing in, lift your arms overhead to lengthen the sides of the body.","Breathing out, tip the pelvis forward and fold from the hips, leading with the chest rather than the head.","Hold the shins, the ankles or the outer edges of the feet, wherever you reach without the back rounding hard, and let the head relax."],"es":["Inhala y levanta los brazos para alargar los costados del cuerpo.","Exhala, inclina la pelvis hacia delante y dobla desde la cadera, guiando el pecho.","Sujeta las espinillas, los tobillos o los bordes de los pies, sin dejar que la espalda se redondee."]},"care":{"en":"Rounding the back to get the head to the knees moves the stretch into the spine. Sit on a folded blanket or a block so the pelvis can tip forward.","es":"Redondear la espalda para llevar la cabeza a las rodillas mueve el estiramiento a la columna. Siéntate sobre una manta doblada o un bloque para inclinar la pelvis."},"img":"images/poses/seated-forward-bend.webp","stepsImg":"images/poses/seated-forward-bend-steps.webp","source":"https://yogaphilippines.com/poses/seated-forward-bend/"},
  {"id":"head-to-knee-pose","name":{"en":"Head to Knee Pose","es":"Cabeza a la rodilla"},"sanskrit":"Janu Sirsasana","level":"gentle","phase":"main","baseSec":90,"helps":["hamstrings","lower-back"],"loads":[],"sessions":["unwind","sleep","desk-reset"],"cue":{"en":"Lengthen on each inhale, soften a little on each exhale.","es":"Alarga en cada inhalación y afloja un poco en cada exhalación."},"steps":{"en":["Bend your right knee and place the sole of the right foot against the inner left thigh. Let the right knee drop out to the side; if it hovers, slide a cushion or block under it.","Turn your chest slightly so your breastbone lines up over the left leg. Loop a strap around the left foot, or rest the hands on the shin.","Inhale and lengthen the spine. Exhale and fold forward from the hips over the left leg, keeping the left knee soft and the left foot gently flexed."],"es":["Flexiona la rodilla derecha y apoya la planta del pie derecho contra la parte interna del muslo izquierdo.","Gira el pecho para que el esternón quede alineado con la pierna izquierda.","Inhala y alarga la columna; exhala y dobla desde la cadera sobre la pierna izquierda."]},"care":{"en":"Pulling the head toward the knee and rounding the upper back moves the stretch away from the hamstrings. Sit higher on a blanket so the pelvis can tip forward.","es":"Tirar de la cabeza hacia la rodilla y redondear la espalda alta aleja el estiramiento de los isquiotibiales. Siéntate más alto sobre una manta para inclinar la pelvis."},"img":"images/poses/head-to-knee-pose.webp","stepsImg":"images/poses/head-to-knee-pose-steps.webp","source":"https://yogaphilippines.com/poses/head-to-knee-pose/"},
  {"id":"happy-baby-pose","name":{"en":"Happy Baby Pose","es":"Postura del Bebé Feliz"},"sanskrit":"Ananda Balasana","level":"gentle","phase":"rest","baseSec":60,"helps":["hips","lower-back"],"loads":[],"sessions":["unwind","sleep","desk-reset"],"cue":{"en":"Knees wide, sacrum heavy.","es":"Rodillas abiertas y sacro pesado."},"steps":{"en":["Draw both knees in toward your chest, then let them open wider than your ribs, toward your armpits.","Reach for the outside edges of your feet, or hold your ankles or shins if the feet are far away.","Gently draw the feet down, so the knees move toward the floor beside your ribs, while the back of the pelvis stays heavy on the mat."],"es":["Acerca ambas rodillas al pecho y ábrelas más que las costillas, hacia las axilas.","Sujeta los bordes exteriores de los pies, o los tobillos o las espinillas si no alcanzas.","Baja los pies con suavidad, dejando el sacro y la pelvis pesados en la manta."]},"care":{"en":"Letting the lower back and tailbone curl off the floor. Loosen your grip until the pelvis settles back down.","es":"Dejar que la zona lumbar y el cóccix se despeguen del suelo. Afloja el agarre hasta que la pelvis vuelva a apoyarse."},"img":"images/poses/happy-baby-pose.webp","stepsImg":"images/poses/happy-baby-pose-steps.webp","source":"https://yogaphilippines.com/poses/happy-baby-pose/"},
  {"id":"reclined-hand-to-big-toe","name":{"en":"Reclined Hand to Big Toe Pose","es":"Mano al dedo grande tumbada"},"sanskrit":"Supta Padangusthasana","level":"gentle","phase":"main","baseSec":90,"helps":["hamstrings","hips"],"loads":[],"sessions":["unwind","sleep"],"cue":{"en":"Both hips level on the floor.","es":"Las dos caderas al mismo nivel en el suelo."},"steps":{"en":["Bend the right knee toward your chest and loop a strap around the ball of the right foot. Hold one end in each hand.","Inhale and straighten the right leg up toward the ceiling only as far as the knee allows. A soft bend is fine. Keep the elbows relaxed and the shoulders on the mat.","Press the back of the left thigh or the left foot into the floor so both hips stay level and grounded. Flex the right foot gently."],"es":["Túmbate boca arriba y lleva la rodilla derecha al pecho, pasando una correa por la planta del pie.","Inhala y estira la pierna derecha hacia el techo solo hasta donde el rodilla permita; un poco de flexión está bien.","Presiona el muslo o el pie izquierdo contra el suelo para que ambas caderas queden niveladas."]},"care":{"en":"Letting the hip of the lifted leg hike up toward the ribs turns the stretch into a pull on the lower back. Keep the bottom knee bent if the back prefers it.","es":"Si la cadera de la pierna levantada sube hacia las costillas, el estiramiento se convierte en un tirón lumbar. Deja la rodilla de abajo flexionada si la espalda lo pide."},"img":"images/poses/reclined-hand-to-big-toe.webp","stepsImg":"images/poses/reclined-hand-to-big-toe-steps.webp","source":"https://yogaphilippines.com/poses/reclined-hand-to-big-toe/"},
  {"id":"savasana-corpse-pose","name":{"en":"Corpse Pose","es":"Postura del Cadáver"},"sanskrit":"Savasana","level":"gentle","phase":"rest","baseSec":150,"helps":["breath","lower-back","neck"],"loads":[],"sessions":["unwind","sleep","wake-up","desk-reset"],"cue":{"en":"Nothing to do. Nothing to fix.","es":"Nada que hacer. Nada que arreglar."},"steps":{"en":["Straighten your legs one at a time and let them fall a little wider than your hips, with the feet flopping open.","Rest your arms a hand's width away from your sides with the palms facing up, and draw the shoulder blades gently under you so the chest feels broad.","Close your eyes and let the breath go back to its own rhythm. Stay for five to ten minutes."],"es":["Estira las piernas una a una y déjalas caer algo más abiertas que las caderas, con los pies cayendo hacia los lados.","Deja los brazos a un palmo del cuerpo, con las palmas hacia arriba, y lleva suavemente los omóplatos bajo el cuerpo.","Cierra los ojos y deja que la respiración vuelva a su propio ritmo. Quédate cinco o diez minutos."]},"care":{"en":"Skipping it to save time. The minutes of stillness at the end are part of the practice. Put a blanket under the knees if the lower back aches.","es":"Saltártela para ganar tiempo. Los minutos de quietud al final son parte de la práctica. Pon una manta bajo las rodillas si te duele la zona lumbar."},"img":"images/poses/savasana-corpse-pose.webp","stepsImg":"images/poses/savasana-corpse-pose-steps.webp","source":"https://yogaphilippines.com/poses/savasana-corpse-pose/"},
  {"id":"legs-up-the-wall","name":{"en":"Legs Up the Wall","es":"Piernas contra la pared"},"sanskrit":"Viparita Karani","level":"gentle","phase":"rest","baseSec":120,"helps":["lower-back","breath","ankles"],"loads":[],"sessions":["unwind","sleep","desk-reset"],"cue":{"en":"Five to ten minutes, breathing through the nose.","es":"De cinco a diez minutos, respirando por la nariz."},"steps":{"en":["Lean back onto one forearm, then swing your legs up the wall as you lower your back to the floor, turning your whole body in one move.","Shuffle your seat as close to the wall as feels easy. If the backs of your legs pull, slide a hand's width or two away; the legs do not need to be straight.","Rest your arms out to the sides with the palms up, or lay your hands on your belly. Let the feet go loose, soles facing the ceiling."],"es":["Apóyate sobre un antebrazo y sube las piernas a la pared al tiempo que bajas la espalda al suelo.","Acerca el buttocks a la pared lo que resulte cómodo; las piernas no tienen que estar rectas.","Deja los brazos a los lados con las palmas hacia arriba y suelta los pies, con las plantas mirando al techo."]},"care":{"en":"Slide a folded blanket under the hips so the pelvis is slightly raised and the tailbone drops over the edge.","es":"Desliza una manta doblada bajo la pelvis para elevarla un poco y que el cóccix caiga sobre el borde."},"img":"images/poses/legs-up-the-wall.webp","stepsImg":"images/poses/legs-up-the-wall-steps.webp","source":"https://yogaphilippines.com/poses/legs-up-the-wall/"},
  {"id":"sphinx-pose","name":{"en":"Sphinx Pose","es":"Postura de la Esfinge"},"sanskrit":"Salamba Bhujangasana","level":"gentle","phase":"main","baseSec":60,"helps":["lower-back","upper-back"],"loads":[],"sessions":["wake-up","desk-reset","unwind"],"cue":{"en":"Lead with the chest, not the chin.","es":"Guide con el pecho, no con el mentón."},"steps":{"en":["Bring your elbows under your shoulders, or a little in front of them, with your forearms parallel and palms down.","Press your forearms lightly into the floor to lift your chest, and let your shoulders slide away from your ears.","Let your belly and legs rest on the mat, and allow the lower back to take a gentle curve without squeezing the buttocks."],"es":["Coloca los codos bajo los hombros, o un poco por delante, con los antebrazos paralelos y las palmas en el suelo.","Presiona los antebrazos en el suelo para elevar el pecho y deja que los hombros se alejen de las orejas.","Deja que la barriga y las piernas descansen en la manta y permite una curva suave en la zona lumbar."]},"care":{"en":"Placing the elbows behind the shoulders drops the chest and crowds the lower back. Put a folded blanket under the hip bones.","es":"Poner los codos detrás de los hombros baja el pecho y apiasta la zona lumbar. Coloca una manta doblada bajo los huesos de la cadera."},"img":"images/poses/sphinx-pose.webp","stepsImg":"images/poses/sphinx-pose-steps.webp","source":"https://yogaphilippines.com/poses/sphinx-pose/"},
  {"id":"cobra-pose","name":{"en":"Cobra Pose","es":"Postura de la Cobra"},"sanskrit":"Bhujangasana","level":"gentle","phase":"main","baseSec":45,"helps":["upper-back","shoulders","lower-back"],"loads":["wrists"],"sessions":["wake-up","desk-reset","unwind"],"cue":{"en":"Use your back first, your hands only lightly.","es":"Usa primero la espalda, y las manos solo ligeramente."},"steps":{"en":["Place your hands flat under your shoulders, fingers pointing forward, and hug the elbows in against your ribs.","Press the pubic bone and the tops of the feet down, and reach the tailbone toward your heels to lengthen the lower back.","On an inhale, lift the forehead and then the chest, using the muscles of your back first and your hands only lightly."],"es":["Coloca las manos planas bajo los hombros, con los dedos hacia delante y los codos pegados a las costillas.","Presiona el pubis y la parte superior de los pies contra el suelo y alarga la zona lumbar.","Inhala y eleva primero la frente, luego el pecho, sin dejar que las manos hagan todo el trabajo."]},"care":{"en":"Straightening the arms and hanging in the lower back crunches the lumbar spine. Stay low in a baby cobra instead.","es":"Estirar los brazos y colgarte de la zona lumbar comprime la columna lumbar. Quédate bajo, en una cobra suave."},"img":"images/poses/cobra-pose.webp","stepsImg":"images/poses/cobra-pose-steps.webp","source":"https://yogaphilippines.com/poses/cobra-pose/"},
  {"id":"locust-pose","name":{"en":"Locust Pose","es":"Postura de la Langosta"},"sanskrit":"Salabhasana","level":"gentle","phase":"main","baseSec":45,"helps":["upper-back","shoulders"],"loads":["lower-back"],"sessions":["wake-up","desk-reset"],"cue":{"en":"Keep the lift moderate rather than straining for height.","es":"Mantén la altura moderada, sin forzarte por llegar más arriba."},"steps":{"en":["Press the tops of the feet and the pubic bone gently into the floor, and lengthen the legs back.","Inhale and lift your head, chest and arms off the floor, keeping the back of the neck long and the gaze on the floor just ahead.","If that feels good, lift the legs as well, keeping the knees straight and the legs no wider than the hips."],"es":["Presiona suavemente la parte superior de los pies y el pubis contra el suelo, alargando las piernas.","Inhala y eleva la cabeza, el pecho y los brazos, manteniendo largo el cuello.","Si te resulta bien, eleva también las piernas, con las rodillas rectas y los pies separados como la anchura de la cadera."]},"care":{"en":"Throwing the head back shortens the back of the neck. Lift only the chest and leave the legs down if the back complains.","es":"Tirar la cabeza hacia atrás acorta la nuca. Eleva solo el pecho y deja las piernas en el suelo si la espalda protesta."},"img":"images/poses/locust-pose.webp","stepsImg":"images/poses/locust-pose-steps.webp","source":"https://yogaphilippines.com/poses/locust-pose/"},
  {"id":"bridge-pose","name":{"en":"Bridge Pose","es":"Postura del Puente"},"sanskrit":"Setu Bandha Sarvangasana","level":"gentle","phase":"main","baseSec":60,"helps":["lower-back","hips"],"loads":[],"sessions":["wake-up","desk-reset","unwind","strong"],"cue":{"en":"Knees tracking over the ankles.","es":"Las rodillas en la misma dirección que los tobillos."},"steps":{"en":["Lie on your back with the knees bent and the feet flat on the mat, hip-width apart and parallel, heels about a hand's length from the buttocks.","Press through the feet, especially the inner edges and the heels, and on an inhale lift the hips off the floor.","Keep the knees pointing straight ahead over the ankles, and let the chest lift toward the chin without pushing the chin down into the chest."],"es":["Túmbate boca arriba con las rodillas flexionadas, los pies en el suelo y los talones a un palmo de los buttocks.","Presiona a través de los pies, sobre todo por los bordes interiores y los talones, y al inhalar eleva la pelvis.","Mantén las rodillas apuntando al frente, sobre los tobillos, y deja que el pecho se eleve sin apretar el mentón."]},"care":{"en":"Letting the knees splay outward shifts the weight onto the outer feet. Slide a block under the sacrum for a supported bridge.","es":"Dejar que las rodillas se abran hacia fuera desplaza el peso a los bordes externos de los pies. Desliza un bloque bajo el sacro para un puente apoyado."},"img":"images/poses/bridge-pose.webp","stepsImg":"images/poses/bridge-pose-steps.webp","source":"https://yogaphilippines.com/poses/bridge-pose/"},
  {"id":"downward-dog","name":{"en":"Downward-Facing Dog","es":"Perro hacia abajo"},"sanskrit":"Adho Mukha Svanasana","level":"steady","phase":"main","baseSec":60,"helps":["hamstrings","shoulders","upper-back"],"loads":["wrists"],"sessions":["wake-up","strong","desk-reset"],"cue":{"en":"Bend the knees until the spine is long, then straighten.","es":"Flexiona las rodillas hasta que la columna esté larga, y después estira las piernas."},"steps":{"en":["Tuck the toes under and, on an exhale, lift the knees off the mat, sending the hips up and back.","Keep the knees bent at first so you can lengthen the spine all the way from the hands to the sitting bones.","Slowly straighten the legs as far as your hamstrings allow, reaching the heels toward the floor without needing them to touch."],"es":["Planta los dedos de los pies y, al exhalar, eleva las rodillas y lleva la pelvis hacia arriba y atrás.","Mantén las rodillas flexionadas al principio para poder alargar toda la columna desde las manos hasta los huesos de la cadera.","Estira las piernas tanto como permitan los isquiotibiales, buscando los talones sin necesidad de que toquen el suelo."]},"care":{"en":"Forcing the heels to the floor while the back rounds. The heels are the last thing to worry about. Take Downward Dog off the table if the wrists complain.","es":"Forzar los talones contra el suelo redondeando la espalda. Los talones son lo último que debe preocuparte. Saca el Perro hacia abajo de la lista si te molestan las muñecas."},"img":"images/poses/downward-dog.webp","stepsImg":"images/poses/downward-dog-steps.webp","source":"https://yogaphilippines.com/poses/downward-dog/"},
  {"id":"warrior-poses","name":{"en":"Warrior Poses","es":"Guerreros I, II y III"},"sanskrit":"Virabhadrasana I, II and III","level":"steady","phase":"main","baseSec":90,"helps":["hips","hamstrings","shoulders","thighs"],"loads":[],"sessions":["wake-up","strong","desk-reset"],"cue":{"en":"Front knee over the ankle, back heel reaching down.","es":"Rodilla delantera sobre el tobillo, talón trasero buscando el suelo."},"steps":{"en":["Warrior II: from a wide stance, turn the right foot out ninety degrees and the left foot in slightly, with the front heel in line with the back arch. Open the hips and chest to the long edge of the mat.","Warrior II: bend the right knee over the ankle, stretch the arms out at shoulder height, and look past the right fingertips. Stay for five breaths.","Warrior III: from a short lunge with the right foot forward, shift your weight into the right leg and hinge forward, lifting the left leg until the body and the lifted leg make one line parallel to the floor."],"es":["Guerrero II: desde una apertura amplia, gira el pie derecho noventa grados y el izquierdo hacia dentro.","Flexiona la rodilla derecha sobre el tobillo, estira los brazos a la altura de los hombros y mira más allá de las yemas de los dedos.","Guerrero III: desde una zancada corta, lleva el peso a la pierna delantera, inclínate y eleva la pierna trasera."]},"care":{"en":"Letting the front knee move past the ankle or cave inward loads the knee from the side. Shorten the stance and lift the back heel if the hips feel tight.","es":"Dejar que la rodilla delantera pase del tobillo o se hunda hacia dentro carga la rodilla de lado. Acorta la zancada y eleva el talón trasero si las caderas van tensas."},"img":"images/poses/warrior-poses.webp","stepsImg":"images/poses/warrior-poses-steps.webp","source":"https://yogaphilippines.com/poses/warrior-poses/"},
  {"id":"triangle-pose","name":{"en":"Triangle Pose","es":"Postura del Triángulo"},"sanskrit":"Trikonasana","level":"steady","phase":"main","baseSec":75,"helps":["hamstrings","hips","lower-back"],"loads":[],"sessions":["wake-up","strong","desk-reset"],"cue":{"en":"Reach from the hip, not from the floor.","es":"Alcanza desde la cadera, no desde el suelo."},"steps":{"en":["Keep both legs straight without locking the knees. Reach your right arm out over the right leg, as if the torso were sliding along a shelf.","When you cannot reach any further, hinge at the right hip and bring the right hand to the shin, the ankle or a block outside the right foot.","Stretch the left arm up toward the ceiling so both arms make one line, and turn your gaze up to the left hand, to the side, or down at the floor."],"es":["Mantén las dos piernas rectas sin bloquear las rodillas y lleva el brazo derecho sobre la pierna derecha.","Cuando no puedas estirar más, dobla desde la cadera derecha y apoya la mano en la espinilla, el tobillo o un bloque.","Estira el brazo izquierdo hacia el techo y gira la mirada a la mano izquierda, o al frente, o al suelo."]},"care":{"en":"Reaching for the floor at the cost of the spine folds the waist and turns the chest to the floor. Rest the lower hand on a block.","es":"Alcanzar el suelo a costa de la columna dobla la cintura y gira el pecho al suelo. Apoya la mano de abajo en un bloque."},"img":"images/poses/triangle-pose.webp","stepsImg":"images/poses/triangle-pose-steps.webp","source":"https://yogaphilippines.com/poses/triangle-pose/"},
  {"id":"extended-side-angle","name":{"en":"Extended Side Angle","es":"Ángulo lateral extendido"},"sanskrit":"Utthita Parsvakonasana","level":"steady","phase":"main","baseSec":75,"helps":["hips","hamstrings","lower-back"],"loads":[],"sessions":["wake-up","strong","desk-reset"],"cue":{"en":"One line from the back heel to the fingertips.","es":"Una sola línea, del talón trasero a las yemas de los dedos."},"steps":{"en":["Tip the torso over the right thigh and rest the right forearm on the thigh, or place the right hand on a block outside the right foot.","Press the outer edge of the back foot down, so the left leg stays strong and straight.","Reach the left arm up, then over the left ear, palm facing down, so one line runs from the back heel to the fingertips."],"es":["Inclina el torso sobre el muslo derecho y apoya el antebrazo derecho en el muslo, o la mano en un bloque fuera del pie derecho.","Presiona el borde exterior del pie trasero contra el suelo, para que la pierna izquierda quede fuerte y recta.","Estira el brazo izquierdo hacia arriba y luego por encima de la oreja izquierda, con la palma hacia abajo."]},"care":{"en":"Letting the front knee cave in toward the big toe. Rest the forearm on the thigh instead of reaching for the floor.","es":"Dejar que la rodilla delantera se hunda hacia el dedo gordo. Apoya el antebrazo en el muslo en lugar de buscar el suelo."},"img":"images/poses/extended-side-angle.webp","stepsImg":"images/poses/extended-side-angle-steps.webp","source":"https://yogaphilippines.com/poses/extended-side-angle/"},
  {"id":"chair-pose","name":{"en":"Chair Pose","es":"Postura de la Silla"},"sanskrit":"Utkatasana","level":"steady","phase":"main","baseSec":45,"helps":["thighs","ankles","upper-back"],"loads":["knees"],"sessions":["strong","wake-up"],"cue":{"en":"Sit back as if onto a chair behind you.","es":"Siéntate hacia atrás como si hubiera una silla detrás."},"steps":{"en":["Breathing in, lift your arms forward and up, shoulder-width apart, palms facing each other.","Breathing out, bend your knees and send your hips back and down, as though you were about to sit on the edge of a stool behind you.","Glance down: you should still see your toes past your knees, and your weight should rest more in your heels than in the balls of your feet."],"es":["Inhala y sube los brazos hacia delante y arriba, a la altura de los hombros, con las palmas una hacia otra.","Exhala, flexiona las rodillas y lleva la pelvis atrás y abajo, como si te sentaras en el borde de un taburete.","Baja la mirada: deberías seguir viendo los dedos de los pies por detrás de las rodillas, y el peso debe estar más en los talones que en la parte delantera."]},"care":{"en":"Letting the knees drift far past the toes moves the weight onto the front of the foot. Take the feet hip-width apart if they knock together.","es":"Dejar que las rodillas pasen de los dedos de los pies mueve el peso a la parte delantera del pie. Pon los pies a la anchura de la cadera si se chocan entre sí."},"img":"images/poses/chair-pose.webp","stepsImg":"images/poses/chair-pose-steps.webp","source":"https://yogaphilippines.com/poses/chair-pose/"},
  {"id":"low-lunge","name":{"en":"Low Lunge","es":"Zancada baja"},"sanskrit":"Anjaneyasana","level":"steady","phase":"main","baseSec":75,"helps":["hips","thighs","hamstrings"],"loads":["knees"],"sessions":["wake-up","strong","desk-reset"],"cue":{"en":"Sink forward into the front of the hip.","es":"Afúndate hacia delante en la parte delantera de la cadera."},"steps":{"en":["Lower the left knee onto a folded blanket and slide it back until the right knee sits over the right ankle.","Rest the top of the back foot on the mat, or tuck the toes if that is kinder to the knee.","Bring your hands to the right thigh or to blocks, and lift the chest so the shoulders sit over the hips."],"es":["Baja la rodilla izquierda sobre una manta doblada y deslízala atrás hasta que la rodilla derecha quede sobre el tobillo derecho.","Apoya la parte superior del pie trasero en la manta, o pliega los dedos si es más amable con la rodilla.","Lleva las manos al muslo derecho y eleva el pecho, con los hombros sobre las caderas."]},"care":{"en":"Letting the front knee drift inward loads the knee from the side. Double the blanket under the back knee if kneeling is uncomfortable.","es":"Dejar que la rodilla delantera se vaya hacia dentro carga la rodilla de lado. Dobla la manta bajo la rodilla trasera si te incomoda arrodillarte."},"img":"images/poses/low-lunge.webp","stepsImg":"images/poses/low-lunge-steps.webp","source":"https://yogaphilippines.com/poses/low-lunge/"},
  {"id":"pyramid-pose","name":{"en":"Pyramid Pose","es":"Postura de la Pirámide"},"sanskrit":"Parsvottanasana","level":"steady","phase":"main","baseSec":75,"helps":["hamstrings","lower-back"],"loads":[],"sessions":["wake-up","strong"],"cue":{"en":"Hinge from the hips with the spine long.","es":"Dobla desde la cadera con la columna larga."},"steps":{"en":["Keep the feet hip-width apart, as if on two rails, and turn both hip points to face the front of the mat.","Place your hands on your hips or on blocks either side of the right foot. Inhale and lengthen the spine forward.","Exhale and hinge from the hips over the right leg, keeping the back long. Keep a soft bend in the front knee if the hamstring pulls."],"es":["Mantén los pies a la anchura de la cadera, como sobre dos raíles, y gira ambos puntos de la cadera hacia el frente de la manta.","Coloca las manos en la cadera o en bloques a los lados del pie derecho. Inhala y alarga la columna hacia delante.","Exhala y dobla desde la cadera sobre la pierna derecha, manteniendo la espalda larga."]},"care":{"en":"Setting the feet on one line makes it hard to balance and twists the hips. Rest the hands on blocks or a chair seat.","es":"Poner los pies en una sola línea dificulta el equilibrio y gira las caderas. Apoya las manos en bloques o en el asiento de una silla."},"img":"images/poses/pyramid-pose.webp","stepsImg":"images/poses/pyramid-pose-steps.webp","source":"https://yogaphilippines.com/poses/pyramid-pose/"},
  {"id":"dolphin-pose","name":{"en":"Dolphin Pose","es":"Postura del Delfín"},"sanskrit":"Ardha Pincha Mayurasana","level":"steady","phase":"main","baseSec":60,"helps":["shoulders","upper-back"],"loads":["wrists"],"sessions":["wake-up","strong","desk-reset"],"cue":{"en":"The head hangs. It does not rest.","es":"La cabeza cuelga. No se apoya."},"steps":{"en":["Come onto hands and knees, then lower onto your forearms with the elbows under the shoulders and the forearms parallel, palms flat.","Tuck your toes, and on an exhale lift your hips up and back, keeping the knees bent at first.","Press firmly down through the forearms and the base of the index fingers, and lift the shoulders away from the floor so the neck stays free."],"es":["Baja a los antebrazos, con los codos bajo los hombros y los antebrazos paralelos, y las palmas planas.","Pliega los dedos de los pies y, al exhalar, eleva la pelvis hacia arriba y atrás, con las rodillas flexionadas al principio.","Presiona los antebrazos y la base de los dedos índice contra el suelo, y aleja los hombros del suelo."]},"care":{"en":"Letting the elbows slide out wider than the shoulders. Keep the knees bent the whole time so the back can stay long.","es":"Dejar que los codos se abran más que los hombros. Mantén las rodillas flexionadas todo el tiempo para que la espalda pueda quedar larga."},"img":"images/poses/dolphin-pose.webp","stepsImg":"images/poses/dolphin-pose-steps.webp","source":"https://yogaphilippines.com/poses/dolphin-pose/"},
  {"id":"tree-pose","name":{"en":"Tree Pose","es":"Postura del Árbol"},"sanskrit":"Vrksasana","level":"steady","phase":"main","baseSec":45,"helps":["hips","breath"],"loads":["ankles"],"sessions":["wake-up","strong","desk-reset","unwind"],"cue":{"en":"Gaze on one point that does not move.","es":"Mira un punto que no se mueva."},"steps":{"en":["Shift your weight into your left foot. Press the big toe, little toe and heel down, and keep a soft bend in the knee rather than locking it.","Lift your right foot and place the sole on your inner left calf or inner left thigh, above or below the knee but never on the joint itself.","Stay for five to eight slow breaths, then lower the foot with control and repeat on the other side."],"es":["Pasa el peso al pie izquierdo y presiona abajo el dedo gordo, el meñique y el talón.","Levanta el pie derecho y apoya la planta en la parte interna de la pantorrilla o del muslo, nunca sobre la rodilla.","Quédate cinco o ocho respiraciones lentas, y baja el pie con control antes de cambiar de lado."]},"care":{"en":"Pressing the foot into the side of the knee puts sideways pressure on a joint. Keep the toes of the lifted foot on the floor as a kickstand.","es":"Presionar el pie contra el lateral de la rodilla somete la articulación a un esfuerzo lateral. Deja la punta del pie elevado en el suelo, a modo de apoyo."},"img":"images/poses/tree-pose.webp","stepsImg":"images/poses/tree-pose-steps.webp","source":"https://yogaphilippines.com/poses/tree-pose/"},
  {"id":"eagle-pose","name":{"en":"Eagle Pose","es":"Postura del Águila"},"sanskrit":"Garudasana","level":"steady","phase":"main","baseSec":45,"helps":["shoulders","upper-back"],"loads":["ankles"],"sessions":["wake-up","strong","unwind"],"cue":{"en":"Sit lower. Straight legs make it harder.","es":"Siéntate más abajo. Con las piernas rectas cuesta más."},"steps":{"en":["Shift your weight onto the left foot. Lift the right leg and cross the right thigh over the left, as high up the thigh as it goes.","Reach the arms forward, cross the left arm over the right at the elbows, bend both elbows and bring the palms toward each other.","Lift the elbows to shoulder height and draw them a little away from your face. Sit lower and stay for five breaths."],"es":["Pasa el peso al pie izquierdo, levanta la pierna derecha y cruza el muslo derecho sobre el izquierdo, tan arriba como puedas.","Estira los brazos al frente, cruza el brazo izquierdo sobre el derecho por los codos y lleva las palmas una hacia otra.","Eleva los codos a la altura de los hombros y quédate cinco respiraciones, sentado más bajo."]},"care":{"en":"Standing tall with straight legs makes the balance much harder. Rest the toes of the crossed leg on the floor instead of hooking the calf.","es":"Quedarte alto con las piernas rectas hace mucho más difícil el equilibrio. Apoya la punta del pie cruzado en el suelo en lugar de enganchar la pantorrilla."},"img":"images/poses/eagle-pose.webp","stepsImg":"images/poses/eagle-pose-steps.webp","source":"https://yogaphilippines.com/poses/eagle-pose/"},
  {"id":"boat-pose","name":{"en":"Boat Pose","es":"Postura del Barco"},"sanskrit":"Navasana","level":"steady","phase":"main","baseSec":45,"helps":["hips","breath","upper-back"],"loads":["lower-back"],"sessions":["strong","wake-up"],"cue":{"en":"Balance just behind the sitting bones.","es":"Equilibra justo detrás de los huesos de la pelvis."},"steps":{"en":["Lean back a little, lengthening from your sit bones to the crown of your head, until you balance just behind the sit bones rather than on your tailbone.","Lift your feet off the floor so your shins are parallel to it, knees still bent. Keep holding the backs of your thighs if you need to.","When the spine stays long, let go and reach your arms forward alongside your legs, palms facing each other."],"es":["Inclínate hacia atrás alargando desde los huesos de la pelvis hasta la coronilla.","Levanta los pies del suelo con las espinillas paralelas a este y las rodillas flexionadas.","Cuando la columna se mantenga larga, suelta las manos y estira los brazos hacia delante, con las palmas una hacia otra."]},"care":{"en":"Rolling back onto the tailbone and rounding the lower back. Keep your hands on the floor behind you, or around the backs of your thighs.","es":"Rodar sobre el cóccix y redondear la zona lumbar. Apoya las manos en el suelo detrás de ti o en la parte trasera de los muslos."},"img":"images/poses/boat-pose.webp","stepsImg":"images/poses/boat-pose-steps.webp","source":"https://yogaphilippines.com/poses/boat-pose/"},
  {"id":"hero-pose","name":{"en":"Hero Pose","es":"Postura del Héroe"},"sanskrit":"Virasana","level":"steady","phase":"main","baseSec":90,"helps":["hips","breath","thighs"],"loads":["knees"],"sessions":["unwind","sleep"],"cue":{"en":"Knee pain means add height, every time.","es":"Dolor de rodilla significa añadir altura, siempre."},"steps":{"en":["Place a block between your feet, on its lowest or middle height.","With your hands, gently roll the calf muscles outward and sit back onto the block.","Sit tall with your hands on your thighs and breathe for one to two minutes."],"es":["Coloca un bloque entre los pies, en la altura más baja o intermedia.","Con las manos, rueda suavemente los gemelos hacia fuera y siéntate sobre el bloque.","Siéntate alto con las manos en los muslos y respira durante uno o dos minutos."]},"care":{"en":"Sitting low without props while the knees ache. Sit on two blocks or a bolster so the knees bend less.","es":"Sentarte bajo sin apoyos mientras duelen las rodillas. Siéntate sobre dos bloques o un cojín para que las rodillas flexionen menos."},"img":"images/poses/hero-pose.webp","stepsImg":"images/poses/hero-pose-steps.webp","source":"https://yogaphilippines.com/poses/hero-pose/"},
  {"id":"saddle-pose","name":{"en":"Saddle Pose","es":"Postura de la Silla de montar"},"sanskrit":"Supta Vajrasana","level":"steady","phase":"main","baseSec":120,"helps":["thighs","hips"],"loads":["knees"],"sessions":["unwind","sleep"],"cue":{"en":"A stretch at the front of the thigh is fine. Pain in the knee joint is not.","es":"Un estiramiento en la parte delantera del muslo está bien. El dolor en la articulación de la rodilla no."},"steps":{"en":["Lean back onto your hands, then onto your forearms, checking the knees and lower back as you go.","If both feel fine, lie back onto the bolster so your back and head are supported. Stay propped higher if you need to.","Stay for one to three minutes to begin, building to five minutes in a Yin class if the knees and back stay comfortable."],"es":["Apóyate en las manos y después en los antebrazos, comprobando las rodillas y la zona lumbar.","Si todo está bien, tumbarte sobre el cojín con la espalda y la cabeza apoyadas.","Quédate de uno a tres minutos para empezar, respirando despacio hacia la barriga."]},"care":{"en":"Pushing into the pose with knee pain. Do the half version: stretch one leg out in front and fold only the other back.","es":"Forzar la postura con dolor de rodilla. Haz la versión media: estira una pierna hacia delante y pliega solo la otra hacia atrás."},"img":"images/poses/saddle-pose.webp","stepsImg":"images/poses/saddle-pose-steps.webp","source":"https://yogaphilippines.com/poses/saddle-pose/"},
  {"id":"staff-pose","name":{"en":"Staff Pose","es":"Postura del Bastón"},"sanskrit":"Dandasana","level":"steady","phase":"main","baseSec":45,"helps":["upper-back","breath","hamstrings"],"loads":[],"sessions":["wake-up","unwind","desk-reset"],"cue":{"en":"Sit on the front of your sitting bones.","es":"Siéntate en la parte delantera de los huesos de la pelvis."},"steps":{"en":["Reach under each buttock and move the flesh back a little so you sit on the front of your sitting bones rather than rolling back.","Place your hands on the floor beside your hips, fingers pointing toward your feet, and press down to lift the chest.","Stack the shoulders over the hips, relax the shoulders away from the ears, and keep the chin level."],"es":["Pasa la mano bajo cada buttocks y lleva un poco de carne hacia atrás, para sentarte en la parte delantera y no rodada.","Pon las manos en el suelo junto a las caderas y empuja hacia abajo para elevar el pecho.","Apila los hombros sobre las caderas, suelta los hombros lejos de las orejas y mantén el mentón nivelado."]},"care":{"en":"Slumping back onto the tailbone rounds the lower back. Sit on a folded blanket or a block so the pelvis can tip forward.","es":"Recostarse sobre el cóccix redondea la zona lumbar. Siéntate sobre una manta doblada o un bloque para inclinar la pelvis."},"img":"images/poses/staff-pose.webp","stepsImg":"images/poses/staff-pose-steps.webp","source":"https://yogaphilippines.com/poses/staff-pose/"},
  {"id":"garland-pose","name":{"en":"Garland Pose","es":"Postura de la Guirnalda"},"sanskrit":"Malasana","level":"steady","phase":"main","baseSec":60,"helps":["hips","thighs"],"loads":["knees","ankles"],"sessions":["desk-reset","wake-up","strong"],"cue":{"en":"Lengthen up, do not fold forward.","es":"Alarga hacia arriba, no te dobles hacia delante."},"steps":{"en":["Bend your knees and lower your hips toward the floor between your heels, keeping your heels down if you can.","Bring your palms together at your chest and press your elbows lightly against the insides of your knees.","Lengthen your spine upward, letting the chest lift away from the thighs rather than rounding forward."],"es":["Flexiona las rodillas y baja la pelvis hacia el suelo entre los talones, manteniendo los talones en el suelo si puedes.","Junta las palmas a la altura del pecho y presiona suavemente los codos contra el interior de las rodillas.","Alarga la columna hacia arriba, dejando que el pecho se aleje de los muslos en vez de redondearse."]},"care":{"en":"Letting the knees collapse inward past the big toes. Slide a rolled blanket under the heels if they lift.","es":"Dejar que las rodillas se hundan más allá de los dedos gordos. Desliza una manta enrollada bajo los talones si se levantan."},"img":"images/poses/garland-pose.webp","stepsImg":"images/poses/garland-pose-steps.webp","source":"https://yogaphilippines.com/poses/garland-pose/"},
  {"id":"camel-pose","name":{"en":"Camel Pose","es":"Postura del Camello"},"sanskrit":"Ustrasana","level":"steady","phase":"main","baseSec":45,"helps":["shoulders","upper-back"],"loads":["neck","lower-back"],"sessions":["wake-up","strong"],"cue":{"en":"The chest rises before anything bends back.","es":"El pecho sube antes de que nada se curve hacia atrás."},"steps":{"en":["Place your hands on the back of your pelvis, fingers pointing down, and draw your tailbone gently toward the floor.","Breathing in, lift your breastbone toward the ceiling, so the chest rises before anything bends back.","Keeping the hips over the knees, lean back only as far as feels controlled. If there is room, reach one hand and then the other to your heels."],"es":["Coloca las manos en la parte trasera de la pelvis y lleva suavemente el cóccix hacia el suelo.","Inhala y eleva el esternón hacia el techo, de modo que el pecho suba antes de que nada se curve hacia atrás.","Manteniendo las caderas sobre las rodillas, inclínate atrás solo hasta donde resulte controlado."]},"care":{"en":"Letting the hips drift back behind the knees turns the pose into a squeeze in the lower back. Keep the hands on the lower back the whole time.","es":"Dejar que las caderas se vayan detrás de las rodillas convierte la postura en un aplastamiento lumbar. Mantén las manos en la zona baja de la espalda todo el tiempo."},"img":"images/poses/camel-pose.webp","stepsImg":"images/poses/camel-pose-steps.webp","source":"https://yogaphilippines.com/poses/camel-pose/"},
  {"id":"fish-pose","name":{"en":"Fish Pose","es":"Postura del Pez"},"sanskrit":"Matsyasana","level":"steady","phase":"main","baseSec":60,"helps":["upper-back","shoulders"],"loads":["neck"],"sessions":["desk-reset","unwind","wake-up"],"cue":{"en":"Lift the chest, not the head.","es":"Eleva el pecho, no la cabeza."},"steps":{"en":["Slide your hands, palms down, under your hips, and draw your elbows in toward your sides.","Press into your forearms and elbows and lift your chest toward the ceiling, arching through the upper back.","Keep your legs active, pressing the thighs down and reaching through the heels."],"es":["Desliza las manos, con las palmas hacia abajo, bajo la pelvis y acerca los codos al cuerpo.","Presiona los antebrazos y los codos y eleva el pecho hacia el techo, arqueando la espalda alta.","Mantén las piernas activas, presionando los muslos hacia el suelo y estirando los talones."]},"care":{"en":"Putting weight on the top of the head compresses the neck. Lie back over a block placed lengthwise under the upper back.","es":"Poner peso sobre la parte superior de la cabeza comprime el cuello. Tumbate sobre un bloque colocado a lo largo de la espalda alta."},"img":"images/poses/fish-pose.webp","stepsImg":"images/poses/fish-pose-steps.webp","source":"https://yogaphilippines.com/poses/fish-pose/"},
  {"id":"wide-squat-pose","name":{"en":"Wide Squat Pose","es":"Agachamiento amplio"},"sanskrit":"Utkata Konasana","level":"steady","phase":"main","baseSec":60,"helps":["thighs","hips","ankles"],"loads":["knees"],"sessions":["wake-up","strong","desk-reset"],"cue":{"en":"Each knee moves in the same direction as its toe.","es":"Cada rodilla se mueve en la misma dirección que su dedo."},"steps":{"en":["Exhale and bend your knees, lowering the hips toward the height of the knees. Keep each knee moving in the same direction as its second toe.","Stack the shoulders over the hips and let the tailbone point down, so the lower back stays long rather than arching.","Bring the arms out to the sides with the elbows bent at right angles and palms forward, or keep the hands at the chest. Stay for five to eight breaths."],"es":["Exhala, flexiona las rodillas y baja la pelvis hasta la altura de las rodillas, manteniendo cada rodilla en la dirección de su dedo.","Apila los hombros sobre las caderas y deja que el cóccix apunte al suelo, para que la zona lumbar quede larga.","Estira los brazos a los lados con los codos a noventa grados, o mantén las manos en el pecho. Quédate cinco respiraciones."]},"care":{"en":"Letting the knees drop inward past the big toes strains the inside of the knee. Keep the bend small and the hands on the hips.","es":"Dejar que las rodillas caigan hacia dentro más allá de los dedos gordos fuerza la parte interna de la rodilla. Haz la flexión pequeña y mantén las manos en la cadera."},"img":"images/poses/wide-squat-pose.webp","stepsImg":"images/poses/wide-squat-pose-steps.webp","source":"https://yogaphilippines.com/poses/wide-squat-pose/"},
  {"id":"upward-facing-dog","name":{"en":"Upward-Facing Dog","es":"Perro hacia arriba"},"sanskrit":"Urdhva Mukha Svanasana","level":"strong","phase":"main","baseSec":30,"helps":["upper-back","shoulders"],"loads":["wrists","lower-back"],"sessions":["strong","wake-up"],"cue":{"en":"Only the hands and the tops of the feet touch.","es":"Solo tocan el suelo las manos y la parte superior de los pies."},"steps":{"en":["Press the tops of the feet down firmly until the knees begin to lift.","Breathe in and straighten the arms, drawing the chest forward and up through the gap between them.","Lift the thighs and knees off the floor, so only the hands and the tops of the feet touch the mat."],"es":["Presiona la parte superior de los pies contra el suelo con firmeza hasta que las rodillas empiecen a elevarse.","Inhala y estira los brazos, llevando el pecho hacia delante y arriba.","Eleva los muslos y las rodillas del suelo, de modo que solo las manos y la parte superior de los pies toquen la manta."]},"care":{"en":"Letting the hips and thighs sag while the arms are straight hangs the weight in the lower back. Do Cobra instead.","es":"Dejar caer la pelvis y los muslos con los brazos rectos cuelga el peso en la zona lumbar. Haz la Cobra en su lugar."},"img":"images/poses/upward-facing-dog.webp","stepsImg":"images/poses/upward-facing-dog-steps.webp","source":"https://yogaphilippines.com/poses/upward-facing-dog/"},
  {"id":"plank-pose","name":{"en":"Plank Pose","es":"Postura de la Plancha"},"sanskrit":"Phalakasana","level":"strong","phase":"main","baseSec":45,"helps":["upper-back","breath"],"loads":["wrists","shoulders"],"sessions":["strong","wake-up"],"cue":{"en":"One line from head to heels.","es":"Una línea de la cabeza a los talones."},"steps":{"en":["Press the whole palm down, especially the base of the index finger, and gently draw the shoulder blades away from your ears.","Step one foot back and then the other, resting on the balls of the feet with the legs straight and about hip-width apart.","Lift the front of the thighs, press back through the heels and draw the lower belly lightly in, so the hips sit level with the shoulders."],"es":["Presiona toda la palma hacia abajo, sobre todo en la base del dedo índice, y aleja suavemente los omóplatos de las orejas.","Lleva un pie atrás y después el otro, apoyado en la parte delantera, con las piernas rectas.","Eleva la parte delantera de los muslos y presiona los talones hacia atrás, con las caderas a la altura de los hombros."]},"care":{"en":"Letting the hips sag toward the floor makes the lower back take the weight. Lower both knees to the mat and keep a straight line from knees to head.","es":"Dejar caer la pelvis hacia el suelo hace que la zona lumbar cargue el peso. Baja las dos rodillas a la manta y mantén una línea recta de las rodillas a la cabeza."},"img":"images/poses/plank-pose.webp","stepsImg":"images/poses/plank-pose-steps.webp","source":"https://yogaphilippines.com/poses/plank-pose/"},
  {"id":"side-plank","name":{"en":"Side Plank","es":"Plancha lateral"},"sanskrit":"Vasisthasana","level":"strong","phase":"main","baseSec":45,"helps":["upper-back","hips"],"loads":["wrists","shoulders"],"sessions":["strong"],"cue":{"en":"Lift out of the wrist, not into it.","es":"Eleva desde la muñeca, no hacia ella."},"steps":{"en":["Shift your weight into your right hand and roll onto the outer edge of your right foot, stacking the left foot on top or placing it on the floor in front.","Press the floor away with the right hand so the shoulder lifts out of the wrist rather than sinking into it.","Lift your hips until the body makes one line again, then reach the left arm up toward the ceiling."],"es":["Pasa el peso a la mano derecha y rueda sobre el canto exterior del pie derecho.","Empuja el suelo con la mano derecha para que el hombro salga de la muñeca en vez de hundirse.","Eleva la pelvis hasta que el cuerpo vuelva a formar una línea y lleva el brazo izquierdo hacia el techo."]},"care":{"en":"Letting the bottom shoulder collapse toward the ear loads the wrist and the shoulder joint. Lower the bottom knee to the mat and lift from there.","es":"Dejar que el hombro de abajo se derrumbe hacia la oreja carga la muñeca y la articulación del hombro. Baja la rodilla de abajo a la manta y levántate desde ahí."},"img":"images/poses/side-plank.webp","stepsImg":"images/poses/side-plank-steps.webp","source":"https://yogaphilippines.com/poses/side-plank/"},
  {"id":"reverse-plank","name":{"en":"Reverse Plank","es":"Plancha inversa"},"sanskrit":"Purvottanasana","level":"strong","phase":"main","baseSec":45,"helps":["upper-back","thighs"],"loads":["wrists","shoulders"],"sessions":["strong"],"cue":{"en":"Press the floor away and keep the hips lifted.","es":"Empuja el suelo y mantén la pelvis elevada."},"steps":{"en":["Bend your elbows slightly, then press into your hands and roll the shoulders back so the chest lifts.","Inhale and press through your heels to lift the hips, until the body makes one line from the shoulders to the ankles. Point the toes toward the floor if you can.","Stay for three to five breaths, pressing the floor away and keeping the hips lifted."],"es":["Flexiona ligeramente los codos y presiona las manos, rodando los hombros atrás para elevar el pecho.","Inhala y presiona los talones para elevar la pelvis, hasta que el cuerpo forme una línea de los hombros a los tobillos.","Quédate tres o cinco respiraciones, manteniendo la pelvis elevada."]},"care":{"en":"Letting the hips sag hangs the weight in the shoulders. Bend the knees with the feet flat for reverse table top.","es":"Dejar caer la pelvis cuelga el peso en los hombros. Flexiona las rodillas con los pies en el suelo para hacer la mesa invertida."},"img":"images/poses/reverse-plank.webp","stepsImg":"images/poses/reverse-plank-steps.webp","source":"https://yogaphilippines.com/poses/reverse-plank/"},
  {"id":"crescent-lunge","name":{"en":"Crescent Lunge","es":"Zancada de la Media Luna"},"sanskrit":"Ashta Chandrasana","level":"strong","phase":"main","baseSec":60,"helps":["thighs","hips","shoulders"],"loads":["knees"],"sessions":["strong","wake-up"],"cue":{"en":"Front knee tracking over the second toe.","es":"Rodilla delantera en la dirección del segundo dedo."},"steps":{"en":["Keep the back knee lifted. Stand on the ball of the left foot, heel reaching back, and press the back thigh up so the back leg is long and strong.","Inhale and rise up, lifting the chest and bringing the shoulders over the hips. Hands can rest on the front thigh or on the hips at first.","Reach the arms overhead, shoulder-width apart, and draw the tailbone gently down so the lower back stays long."],"es":["Mantén la rodilla trasera elevada, ponte sobre la parte delantera del pie izquierdo y empuja el muslo trasero hacia arriba.","Inhala y sube, elevando el pecho y trayendo los hombros sobre las caderas.","Estira los brazos hacia arriba, separados a la altura de los hombros, y baja suavemente el cóccix."]},"care":{"en":"Letting the front knee drift past the ankle or cave inward. Lower the back knee onto a blanket and use Low Lunge instead.","es":"Dejar que la rodilla delantera pase del tobillo o se hunda hacia dentro. Baja la rodilla trasera sobre una manta y usa la Zancada baja."},"img":"images/poses/crescent-lunge.webp","stepsImg":"images/poses/crescent-lunge-steps.webp","source":"https://yogaphilippines.com/poses/crescent-lunge/"},
  {"id":"half-moon-pose","name":{"en":"Half Moon Pose","es":"Postura de la Media Luna"},"sanskrit":"Ardha Chandrasana","level":"strong","phase":"main","baseSec":45,"helps":["hips","thighs"],"loads":["ankles","shoulders"],"sessions":["strong"],"cue":{"en":"Stack the hips over the standing leg.","es":"Apila las caderas sobre la pierna de apoyo."},"steps":{"en":["Shift your weight into the right foot and hand, and lift the left leg until it is level with the hip, foot flexed.","Straighten the right leg without locking it, and stack the left hip over the right.","Turn the chest toward the long edge of the mat and reach the left arm up, or keep the left hand on the hip."],"es":["Pasa el peso al pie derecho y a la mano, y eleva la pierna izquierda hasta que esté a la altura de la cadera.","Estira la pierna derecha sin bloquear la rodilla y apila la cadera izquierda sobre la derecha.","Gira el pecho hacia el lado largo de la manta y lleva el brazo izquierdo hacia arriba."]},"care":{"en":"Letting the lifted leg drift forward of the body folds the hips toward the floor. Practise with your back against a wall.","es":"Dejar que la pierna elevada se vaya hacia delante del cuerpo dobla las caderas hacia el suelo. Practica con la espalda contra una pared."},"img":"images/poses/half-moon-pose.webp","stepsImg":"images/poses/half-moon-pose-steps.webp","source":"https://yogaphilippines.com/poses/half-moon-pose/"},
  {"id":"dancer-pose","name":{"en":"Dancer Pose","es":"Postura del Bailarín"},"sanskrit":"Natarajasana","level":"strong","phase":"main","baseSec":45,"helps":["shoulders","thighs"],"loads":["ankles","lower-back"],"sessions":["strong","unwind"],"cue":{"en":"Hips level, standing knee soft.","es":"Caderas niveladas y rodilla de apoyo flexible."},"steps":{"en":["Shift your weight onto the left foot. Bend the right knee and hold the inside of the right foot or ankle with the right hand, knees side by side.","Press the right foot back into your hand. As the foot moves back and up, let the chest tip forward a little to balance it.","Keep the hips level and the standing knee soft. Stay for three to five breaths with your gaze on one still point."],"es":["Pasa el peso al pie izquierdo, flexiona la rodilla derecha y sujeta la parte interior del pie o del tobillo con la mano derecha.","Presiona el pie derecho hacia atrás contra tu mano. A medida que el pie va atrás y arriba, deja que el pecho se incline un poco hacia delante para equilibrarlo.","Mantén las caderas niveladas y la rodilla de apoyo blanda. Quédate tres o cinco respiraciones con la mirada en un punto fijo."]},"care":{"en":"Letting the lifted knee swing out to the side twists the lower back. Loop a strap around the lifted foot if you cannot reach it.","es":"Dejar que la rodilla elevada se balancee hacia un lado gira la zona lumbar. Pasa una correa por el pie elevado si no alcanzas."},"img":"images/poses/dancer-pose.webp","stepsImg":"images/poses/dancer-pose-steps.webp","source":"https://yogaphilippines.com/poses/dancer-pose/"},
  {"id":"lizard-pose","name":{"en":"Lizard Pose","es":"Postura de la Lagartija"},"sanskrit":"Utthan Pristhasana","level":"strong","phase":"main","baseSec":75,"helps":["hips","thighs","hamstrings"],"loads":["knees"],"sessions":["strong","wake-up"],"cue":{"en":"Lower only as far as the hips allow.","es":"Baja solo hasta donde permitan las caderas."},"steps":{"en":["Lower your left knee onto a folded blanket and slide it back until the right knee sits over or just behind the right ankle.","Keep your hands under your shoulders, or place your forearms on a block or two. Lower only as far as the hips allow.","Lengthen through the chest so the back stays long, and let the hips ease forward and down. Keep the right knee pointing the same way as the toes."],"es":["Baja la rodilla izquierda sobre una manta doblada y deslízala atrás hasta que la rodilla derecha quede sobre o justo detrás del tobillo derecho.","Mantén las manos bajo los hombros, o apoya los antebrazos en un bloque. Baja solo hasta donde permitan las caderas.","Alarga el pecho para que la espalda quede larga y deja que las caderas se afunden hacia delante y abajo."]},"care":{"en":"Letting the front knee drift toward the midline or travel far past the ankle. Keep the hands on blocks instead of lowering to the forearms.","es":"Dejar que la rodilla delantera se vaya hacia la línea media o pase demasiado del tobillo. Mantén las manos en bloques en lugar de bajar a los antebrazos."},"img":"images/poses/lizard-pose.webp","stepsImg":"images/poses/lizard-pose-steps.webp","source":"https://yogaphilippines.com/poses/lizard-pose/"},
];
